28	use typst_library::engine::{Engine, Route, Sink, Traced};
29	use typst_library::foundations::{Context, Module, NativeElement, Scope, Scopes, Value};
30	use typst_library::introspection::{EmptyIntrospector, Introspector};
31	use typst_library::math::EquationElem;
32	use typst_library::routines::SpanMode;
33	use typst_library::{Library, World};
34	use typst_syntax::{Source, SyntaxMode, ast, parse, parse_code, parse_math};
35	use typst_utils::{LazyHash, Protected};
36	
37	/// Evaluate a source file and return the resulting module.
38	#[comemo::memoize]
39	#[typst_macros::time(name = "eval", span = source.root().span())]
40	pub fn eval(
41	    world: Tracked<dyn World + '_>,
42	    library: &LazyHash<Library>,
43	    traced: Tracked<Traced>,
44	    sink: TrackedMut<Sink>,
45	    route: Tracked<Route>,
46	    source: &Source,
47	) -> SourceResult<Module> {
48	    // Prevent cyclic evaluation.
49	    let id = source.id();
50	    if route.contains(id) {
51	        panic!("Tried to cyclicly evaluate {:?}", id.vpath());
52	    }
53	
54	    // Prepare the engine.
55	    let introspector = EmptyIntrospector;
56	    let engine = Engine {
57	        library,
58	        world,
59	        introspector: Protected::new(introspector.track()),
60	        traced,
61	        sink,
62	        route: Route::extend(route).with_id(id),
63	    };
64	
65	    // Prepare VM.
